//! Revision editing and the shared view/sheet drawing payload.
use serde_json::{json,Value};
use openarch_model::{Document,Element,Id};
use openarch_model::revisions::*;
use crate::{Session,Res};

pub(crate) fn drawing(d:&Document,view:Id)->Value{
    let sheet=if d.sheet(view).is_some(){Some(view)}else{d.sheet_of_view(view).map(|(s,_)|s)};
    let hidden=d.view(view).map(|v|&v.hidden_elements);
    let settings=d.revision_settings();let view_settings=d.effective_settings(view).unwrap_or_default();let shown=|category:&str|view_settings.overrides.annotation.get(category).is_none_or(|o|o.visible);
    let clouds:Vec<_>=d.revision_clouds(view).into_iter().filter_map(|(id,c)|{let r=d.revision_record(c.revision)?;if hidden.is_some_and(|h|h.contains(&id)){return None;}Some(json!({"id":id,"revision":c.revision,"number":d.revision_number(c.revision,sheet),"issued":r.issued,"pinned":c.pinned,"inverted":c.inverted,"visible":r.visibility==RevisionVisibility::CloudsAndTags&&shown("Revision Clouds"),"style":crate::graphics::style_for(d,&view_settings,"Revision Clouds",None,d.view(view).and_then(|v|v.element_overrides.get(&id)),"normal",&crate::graphics::Hint::default()),"curves":c.curves,"paths":c.curves.iter().map(|c|c.tessellate(1.0).iter().map(|p|[p.x,p.y]).collect::<Vec<_>>()).collect::<Vec<_>>(),"arc_mm":settings.arc_length_mm}))}).collect();
    let tags:Vec<_>=d.revision_tags(view).into_iter().filter_map(|(id,t)|{let Some(Element::RevisionCloud(c))=d.get(t.cloud)else{return None};let r=d.revision_record(c.revision)?;if !shown("Revision Tags")||r.visibility==RevisionVisibility::None||hidden.is_some_and(|h|h.contains(&id)||h.contains(&t.cloud)){return None;}let f=t.family.and_then(|id|d.annotation_family(id));let labels=f.map(|f|d.symbol_texts(f,&|p|Some(match p{"Revision Number"=>d.revision_number(c.revision,sheet),"Revision Description"=>r.description.clone(),"Revision Date"=>r.date.clone(),_=>return None}),false)).unwrap_or_default();Some(json!({"id":id,"cloud":t.cloud,"at":t.at,"anchor":c.curves.first().map(|c|c.start()),"pinned":t.pinned,"leader":t.leader,"family":f.map(|f|d.symbol_drawing(f,false)),"labels":labels}))}).collect();json!({"revision_clouds":clouds,"revision_tags":tags})
}

impl Session{
    pub(crate) fn revision_data(&self)->Value{let d=&self.doc;json!({"settings":d.revision_settings(),"revisions":d.revisions().into_iter().map(|(id,r)|{let mut v=serde_json::to_value(r).unwrap();v["id"]=json!(id);v["number"]=json!(d.revision_number(id,None));v}).collect::<Vec<_>>(),"title_blocks":d.annotation_families().into_iter().filter(|(_,f)|f.kind==openarch_model::annotation::AnnotationKind::TitleBlock).map(|(id,f)|json!({"id":id,"name":f.name,"paper":f.paper_mm,"table":f.revision_schedule})).collect::<Vec<_>>()})}
    pub(crate) fn revision_table(&self,sheet:Id)->Value{let d=&self.doc;let Some(s)=d.sheet(sheet)else{return Value::Null};let Some(style)=s.title_block.and_then(|id|d.annotation_family(id)).and_then(|f|f.revision_schedule.as_ref())else{return Value::Null};let mut ids=d.sheet_revisions(sheet);if let Some(n)=style.fixed_rows{ids=ids.into_iter().rev().take(n).collect();ids.reverse();}if style.newest_first{ids.reverse();}json!({"style":style,"rows":ids.into_iter().map(|id|json!({"id":id,"cells":style.columns.iter().map(|c|d.revision_value(id,Some(sheet),&c.field)).collect::<Vec<_>>()})).collect::<Vec<_>>()})}
    pub(crate) fn set_revision_table(&mut self,p:&Value)->Res{let id=crate::id_of(p,"family_id")?;let mut family=self.doc.annotation_family(id).cloned().ok_or("Choose a title block family")?;if family.kind!=openarch_model::annotation::AnnotationKind::TitleBlock{return Err("Choose a title block family".into());}let table:Option<RevisionTable>=serde_json::from_value(p["table"].clone()).map_err(|e|e.to_string())?;if let Some(t)=&table{t.check()?;if ![0,90,270].contains(&t.rotation)||t.columns.is_empty()||t.columns.len()>12||t.columns.iter().any(|c|!REVISION_FIELDS.contains(&c.field.as_str())||!c.width_mm.is_finite()||c.width_mm<5.0)||!t.at.iter().all(|v|v.is_finite())||!t.row_height_mm.is_finite()||!t.text_mm.is_finite()||t.row_height_mm<3.0||t.text_mm<0.5||t.text_mm>t.row_height_mm||t.fixed_rows.is_some_and(|n|n==0||n>1000){return Err("Check the table columns, size and rotation.".into());}}family.revision_schedule=table;self.doc.transact("Title block revision table",|tx|tx.update(id,Element::AnnotationFamily(family)))?;Ok(json!({}))}
    pub(crate) fn revision_properties(&self,id:Id)->Res{let d=&self.doc;match d.get(id){
        Some(Element::Revision(r))=>{let ro=r.issued;let text=|label:&str,path:&str,value:&str|json!({"label":label,"path":path,"kind":if ro{"ro"}else{"text"},"value":value});Ok(json!({"id":id,"kind":"Revision","category":"Revisions","title":format!("Revision {}",d.revision_number(id,None)),"type_label":"Revision","target":{"method":"patch_revision","id":id},"groups":[{"name":"Identity Data","rows":[{"label":"Number","kind":"ro","value":d.revision_number(id,None)},{"label":"Sequence","kind":"ro","value":(r.order+1).to_string(),"raw":r.order+1},text("Date","date",&r.date),text("Description","description",&r.description),text("Issued To","issued_to",&r.issued_to),text("Issued By","issued_by",&r.issued_by),{"label":"Issued","path":"issued","kind":"bool","raw":r.issued,"value":if r.issued{"Yes"}else{"No"}}]}]}))},
        Some(Element::RevisionCloud(c))=>Ok(json!({"id":id,"kind":"RevisionCloud","category":"Revision Clouds","title":"Revision Cloud","type_label":"Revision Cloud","target":{"method":"patch_revision_cloud","id":id},"groups":[{"name":"Identity Data","rows":[{"label":"Revision","kind":"select","value":d.revision_number(c.revision,None),"options":d.revisions().into_iter().filter(|(id,r)|!r.issued||*id==c.revision).map(|(id,r)|json!({"label":format!("{} {}",d.revision_number(id,None),r.description),"selected":id==c.revision,"patch":{"revision":id}})).collect::<Vec<_>>()},{"label":"Comments","path":"comments","kind":"text","value":c.comments},{"label":"Mark","path":"mark","kind":"text","value":c.mark},{"label":"Arc Direction","path":"inverted","kind":"bool","raw":c.inverted,"value":if c.inverted{"Inward"}else{"Outward"}},{"label":"Pinned","path":"pinned","kind":"bool","raw":c.pinned,"value":if c.pinned{"Yes"}else{"No"}}]}]})),
        Some(Element::RevisionTag(t))=>Ok(json!({"id":id,"kind":"RevisionTag","title":"Revision Tag","type_label":"Revision Tag","target":{"method":"patch_revision_tag","id":id},"groups":[{"name":"Graphics","rows":[{"label":"Leader","path":"leader","kind":"bool","raw":t.leader,"value":if t.leader{"Yes"}else{"No"}},{"label":"Family","kind":"select","value":t.family.and_then(|id|d.annotation_family(id)).map(|f|f.name.clone()).unwrap_or_default(),"options":d.annotation_families().into_iter().filter(|(_,f)|f.kind==openarch_model::annotation::AnnotationKind::RevisionTag).map(|(id,f)|json!({"label":f.name,"selected":Some(id)==t.family,"patch":{"family":id}})).collect::<Vec<_>>()}]}]})),_=>Err("not a revision element".into())}}
}
